<?php
namespace App\Http\Controllers;
use App\Models\Reclamation; use App\Models\DemandeAssistance; use Illuminate\Support\Facades\DB;
class DashboardController extends Controller {public function index(){ $r=Reclamation::query();$a=DemandeAssistance::query();$active=['recu','a_affecter','affecte','en_cours','en_attente_information'];return view('dashboard.index',['totalReclamations'=>(clone $r)->count(),'totalAssistance'=>(clone $a)->count(),'enCours'=>(clone $r)->whereIn('statut',$active)->count()+(clone $a)->whereIn('statut',$active)->count(),'enRetard'=>(clone $r)->whereNotIn('statut',['traite','cloture','annule'])->whereNotNull('echeance_traitement')->where('echeance_traitement','<',now())->count()+(clone $a)->whereNotIn('statut',['traite','a_notifier','cloture','annule'])->whereNotNull('echeance_traitement')->where('echeance_traitement','<',now())->count(),'recentReclamations'=>Reclamation::latest('created_at')->take(5)->get(),'recentAssistance'=>DemandeAssistance::latest('created_at')->take(5)->get(),'retards'=>DB::table('v_dossiers_en_retard')->orderByDesc('retard_heures')->limit(10)->get()]);}}
